    'asterisk_settings.status_prompt_title' => 'Puhuttu tilaviesti äänimerkkien sijaan',
    'asterisk_settings.status_prompt_help' => 'Kun puhelu alanumeroon päättyy siksi, että se on varattu, ei vastaa tai sitä ei tavoiteta (eikä vastaaja tai soitonsiirto ota sitä vastaan), soittaja voi kuulla lyhyen viestin omalla kielellään pelkän äänimerkin sijaan. Trunkeista tulevat puhelut kuulevat sen ennen vastaamista, joten niitä ei laskuteta; faksit eivät kuule mitään. Tulee voimaan Käytä-painikkeen jälkeen.',
