    'asterisk_settings.vm_weak_pins' => '%d vastaajalaatikolla on PIN-koodi, joka ei noudata näitä sääntöjä (usein alanumero). Aseta uusi PIN-koodi alanumerolle tai kohdassa Oma puhelin.',
