    'asterisk_settings.video_codec_help' => 'Yksi koodekki kaikille puhelimille: Asterisk ei muunna videota, ja puhelu, jonka osapuolet lähettävät eri videokoodekeilla, katkeaisi. Puhelin ilman tätä koodekkia puhuu ilman videota. H.264:llä mobiilisovellus tarvitsee puhelimen, joka osaa koodata H.264:ää.',
    'asterisk_settings.video_calls_help' => 'Kun videopuhelut ovat päällä, verkkopuhelin saa valintakentän viereen <strong>videopuhelu</strong>-painikkeen ja saapuvaan videopuheluun voi vastata videolla; mobiilisovellukset tarjoavat <em>Videopuhelu</em>-toiminnon kollegoille. Video vie moninkertaisesti kaistaa ääneen verrattuna; pidä se pois päältä, kunnes verkko on valmis. Käyttäjät tarvitsevat myös <em>video</em>-puhelintilan.',
