    'region.title' => 'Aikavyöhyke ja äänimerkit',
    'region.help' => 'Yksi aikavyöhyke palvelimelle, portaalille, puhelutietueille ja aikaehdoille. Sen muuttaminen käynnistää tietokannan, Asteriskin ja portaalin uudelleen muutamassa sekunnissa ja käynnissä olevat puhelut katkeavat, joten valitse rauhallinen hetki. Aikaehtojen työajat noudattavat sen jälkeen uutta aikavyöhykettä. Äänimerkit ovat soitto- ja varattuääniä, jotka soittajat kuulevat; niiden muuttaminen ei häiritse puheluita.',
    'region.mismatch' => 'Palvelin käyttää aikavyöhykettä %1$s, mutta portaali aikavyöhykettä %2$s, joten ajat portaalissa ja puhelujen käsittelyssä voivat erota toisistaan. Valitse toinen alta.',
