    'trunks.connection_mode_register' => 'Saapuva rekisteröinti (vastapää rekisteröityy meille)',
    'trunks.connection_mode_help' => 'IP-pohjainen: vastapää tunnistetaan IP-osoitteensa perusteella, ja sen contact pidetään kiinteänä — suositeltu tila samassa verkossa olevalle kiinteän IP:n vastapäälle. Saapuva rekisteröinti: vastapää lähettää meille SIP REGISTER -viestin, ja sen osoite opitaan rekisteröinnistä. Tämä tila vaatii käyttäjätunnuksen ja salasanan; vastapää tunnistautuu niillä sekä rekisteröinnissä että puheluissa.',
