    'backup.page_title' => 'Varmuuskopiointi ja palautus',
    'backup.help_title' => 'Mitä varmuuskopio sisältää?',
    'backup.help_body' => 'Tietokannan ja asetukset: asetustiedot, varmenteet, ladatut äänet ja jonotusmusiikit, lisäosat sekä salaisuuksien salauksen purkuavaimen. Puhelutallenteet ja faksit eivät sisälly varmuuskopioon. Varmuuskopio luodaan joka yö, ja vanhat poistetaan alla määritetyn päivämäärän jälkeen.<br><br><strong>Säilytä ladatut varmuuskopiot turvassa:</strong> ne sisältävät järjestelmän kaikki salasanat ja salaiset avaimet.<br><br><strong>Palautus korvaa nykyiset tiedot</strong> varmuuskopion tiedoilla, ja kaikki sen jälkeen tehty menetetään. Palvelut käynnistyvät uudelleen ja meneillään olevat puhelut katkeavat. Nykyisestä tilasta luodaan ensin varmuuskopio, joka palautetaan takaisin, jos palautus epäonnistuu.',
