    'system_update.page_title' => 'Järjestelmäpäivitys',
    'system_update.help_title' => 'Miten päivitys toimii?',
    'system_update.help_body' => 'Päivitys varmuuskopioi ensin tietokannan, asetukset ja Asterisk-määritykset, asentaa sitten uuden version ja testaa, että kaikki toimii. Jos jokin epäonnistuu, palataan automaattisesti edelliseen versioon. Asterisk käynnistetään uudelleen vain silloin, kun päivitys vaatii sen (uusi Asterisk-määritys tai -paketti); siitä ilmoitetaan alla tällä sivulla. Tällaisessa päivityksessä valitset, mitä käynnissä oleville puheluille tapahtuu: odota niiden päättymistä tai lopeta ne. Odotuksen aikana voit silti lopettaa ne tai peruuttaa päivityksen. Puhelu, joka alkaa odotuksen jälkeen itse päivityksen aikana, myös katkeaa. Kaikki muut päivitykset vain lataavat Asteriskin uudelleen, ja puhelut jatkuvat. Asennuskansion alla olevat käsin muokatut tiedostot eivät estä päivitystä: ne tallennetaan sen varmuuskopioon ja säilytetään, ellei uusi versio muuta samaa tiedostoa. Tällöin käytetään uutta versiota ja sivun loki ilmoittaa tiedoston. Päivityksen voi ajaa myös palvelimella: <code>sudo aipbx-update</code>',
    'system_update.current' => 'Asennettu versio',
