    'scheduled_tasks.help_title' => 'Hiekkalaatikoidut ajoitetut komentosarjat',
    'scheduled_tasks.help_body' => 'Suorita shell-, PHP- tai Python-komentosarjoja cron-aikataulun mukaan systemd-hiekkalaatikossa: etuoikeudettomana käyttäjänä aipbx-task (ei koskaan root, ei koskaan verkkopalvelin), vain tehtävän oma kansio kirjoitettavana, muisti- ja suoritinrajoitukset sekä ilman verkkoyhteyttä, ellei sitä ole sallittu. Järjestelmä käynnistää ne minuutin välein; "Suorita nyt" käynnistää tehtävän minuutin kuluessa. Epäonnistuneesta suorituksesta tulee hälytys kelloon.',
