    'certificates.header_title' => 'TLS-varmenne',
    'certificates.help_title' => 'Varmenneopas',
    'certificates.help_body' => 'Portaali (HTTPS), WebRTC TURNS ja SIP-TLS/WSS käyttävät yhteistä varmennetta; täällä tehdyt muutokset otetaan käyttöön samanaikaisesti Apachessa, coturnissa ja Asteriskissa. <b>Let\'s Encrypt</b> on maksuton ja uusiutuu itsestään; verkkotunnuksen on osoitettava tähän palvelimeen ja portin 80 on oltava tavoitettavissa internetistä. Jos organisaatiollasi on oma varmenne, <b>lataa se</b> (PEM tai PFX); ladatut varmenteet eivät uusiudu automaattisesti, joten lataa uusi ennen vanhan vanhenemista. <b>Itse allekirjoitetulla</b> varmenteella selaimet näyttävät varoituksen eikä TURNS toimi selaimissa: palomuurien takana olevissa WebRTC-puheluissa ei välttämättä kuulu ääntä.',
