    'queue_reports.help_title' => 'Jonoraporttien opas',
    'queue_reports.help_body' => 'Jokainen jonoon tuleva puhelu lasketaan kerran. <b>Vastattu</b>: yhdistetty agenttiin. <b>Menetetty</b>: soittaja katkaisi odottaessaan tai jonon aikakatkaisu umpeutui. <b>Lyhyt luopuminen</b>: katkaistu %d sekunnin kuluessa; jätetään palvelutason ulkopuolelle. <b>Palvelutaso</b>: tavoiteajassa vastatut puhelut suhteessa kaikkiin puheluihin lyhyitä luopumisia lukuun ottamatta. <b>ASA</b>: vastattujen puhelujen keskimääräinen odotusaika. <b>AHT</b>: keskimääräinen puheaika. <b>Vastausaste</b> (agentti): kuinka usein agentti vastasi, kun jono soitti hänelle. <b>Takaisinsoitto</b>: menetetty puhelu katsotaan hoidetuksi, kun numeroon soitettiin myöhemmin alanumerosta tai numerosta soitettiin uudelleen ja puheluun vastattiin. Tiedot tulevat Asteriskin jonolokista; raportin voi ladata PDF- tai Excel-muodossa.',
