    'ai_cloud.help_title' => 'Pilven AI-palvelut',
    'ai_cloud.help_body' => 'Pilven AI-palveluntarjoajien tilit yhdessä paikassa: puhe, puhe tekstiksi, kielimallit (Gemini, Gemma, GPT, Llama …) ja upotukset (embeddings). Syötä avain, testaa se ja valitse kullekin tehtävälle ja kielelle käytettävä moottori: tämän palvelimen paikallinen malli tai pilvipalvelu. Ilmaiset tasot on merkitty; kuluvan kuukauden käyttö näkyy jokaisen palveluntarjoajan kohdalla.',
    'ai_cloud.privacy' => 'Pilvimoottori lähettää äänen tai tekstin kyseiselle palveluntarjoajalle. Tarkista sen ehdot ja tietosuojavelvoitteesi (GDPR) ennen valintaa; paikalliset mallit pitävät kaiken tällä palvelimella.',
