    'ai_cloud.vm_title' => 'Vastaajaviesti tekstinä',
    'ai_cloud.vm_help' => 'Uusi vastaajaviesti kirjoitetaan tekstiksi yllä vaihteen kielelle valitulla puheentunnistuksella ja tiivistetään kielimallilla yhteen lauseeseen. Teksti tulee vastaajaviestin sähköpostiin (mallin muuttuja {ai_text}), sovelluksen ilmoitukseen ja vastaajaviestilistoihin. Pilvimoottorilla tallenne tai sen teksti lähetetään kyseiselle palveluntarjoajalle.',
