    'ai_tts.title' => 'Pilvi-TTS (tekstistä puheeksi)',
    'ai_tts.help_title' => 'Pilvi-TTS-opas',
    'ai_tts.help_body' => 'Muuntaa tekstin luonnolliseksi puheeksi pilvipalveluiden avulla (Google, Amazon Polly, Azure, ElevenLabs, OpenAI). Kuuntele tulos, lataa se MP3-tiedostona tai tallenna se yhdellä napsautuksella <b>tiedotteeksi</b>: se muunnetaan Asteriskin muotoon (8 kHz WAV) ja lisätään kohtaan Äänet &amp; tiedotteet IVR:ien, saapuvien reittien ja aikaehtojen käyttöön (tulee voimaan Ota käyttöön -toiminnon jälkeen). <b>Nämä palvelut ovat maksullisia</b> ja laskuttavat merkkimäärän mukaan; jokainen synteesi tallennetaan historiaan merkkimäärineen. Käyttöavaimet saadaan kunkin palveluntarjoajan konsolista, ne tallennetaan salattuina eikä niitä näytetä sivulla enää uudelleen.',
    'ai_tts.tab_speak' => 'Syntetisoi',
