    'mailtpl.invite_new.subject' => '[{brand}] Tilisi on luotu - aseta salasana',
    'mailtpl.invite_new.body' => '<p>Hei {name},</p>{mobile_section}<p>Tilisi vaihteessa <strong>{brand}</strong> on valmis. Kirjautuaksesi aseta salasana alla olevalla painikkeella.</p>{account_details}{reset_button}<p>Jos painike ei toimi, avaa tämä linkki: {reset_link}</p><p><em>Salasanalinkki on voimassa 48 tuntia ja toimii kerran. Jos et odottanut tätä viestiä, ota yhteyttä järjestelmänvalvojaan.</em></p>',
    'mailtpl.invite.subject' => '[{brand}] Kirjautumis- ja salasanalinkkisi',
    'mailtpl.invite.body' => '<p>Hei {name},</p>{mobile_section}<p>Tässä on uusi linkki salasanan asettamiseen palveluun <strong>{brand}</strong>.</p>{account_details}{reset_button}<p>Jos painike ei toimi, avaa tämä linkki: {reset_link}</p><p><em>Salasanalinkki on voimassa 48 tuntia ja toimii kerran. Jos et pyytänyt sitä, ota yhteyttä järjestelmänvalvojaan.</em></p>',
    'mailtpl.login_new_ip.subject' => '[{brand}] Uusi kirjautuminen tilillesi',
    'mailtpl.login_new_ip.body' => '<p>Hei {name},</p><p>Tilillesi <strong>{username}</strong> kirjauduttiin verkosta, jota se ei ole hiljattain käyttänyt.</p><ul><li>Osoite: {ip}</li><li>Aika: {date}</li><li>Selain tai sovellus: {browser}</li></ul><p>Jos tämä olit sinä, sinun ei tarvitse tehdä mitään. Jos se et ollut sinä, jollakulla on salasanasi: avaa <a href="{portal_link}">portaali</a>, valitse "Unohditko salasanasi?" ja ilmoita ylläpitäjällesi.</p>',
    'login_alert.title' => 'Kirjautumisilmoitukset',
    'login_alert.help' => 'Lähettää käyttäjälle sähköpostia, kun hänen tililleen kirjaudutaan internetverkosta, jota ei ole käytetty viimeisen 90 päivän aikana. Väärät salasanat käsitellään tilin lukituksilla ja Fail2banilla; tämä kattaa toimivan varastetun salasanan. Se vaatii sähköpostiasetukset ja käyttäjän sähköpostiosoitteen. Oman LAN- tai VPN-verkon osoitteita ei lasketa mukaan.',
    'login_alert.enable' => 'Lähetä käyttäjille sähköpostia uudesta verkosta tehdyistä kirjautumisista',
    'login_alert.saved' => 'Kirjautumisilmoitusten asetus tallennettiin.',
    'mailtpl.password_reset.subject' => '[{brand}] Nollaa salasanasi',
    'mailtpl.password_reset.body' => '<p>Hei {name},</p><p>Tilisi <strong>{username}</strong> salasanan nollausta on pyydetty.</p>{reset_button}<p>Jos painike ei toimi, avaa tämä linkki: {reset_link}</p><p><em>Linkki on voimassa 30 minuuttia. Jos et pyytänyt sitä, voit jättää tämän viestin huomiotta; salasanasi pysyy ennallaan.</em></p>',
    'mailtpl.voicemail.subject' => 'Uusi vastaajaviesti: {caller} ({duration})',
    'mailtpl.voicemail.body' => '<p>Hei {name},</p><p>Vastaajaasi <strong>{mailbox}</strong> on tullut uusi viesti.</p><ul><li><strong>Lähettäjä:</strong> {caller}</li><li><strong>Vastaanotettu:</strong> {date}</li><li><strong>Kesto:</strong> {duration}</li></ul>{ai_text}<p>Jos tallenne on liitteenä, voit toistaa sen suoraan tästä. Voit kuunnella sen myös portaalissa ({portal_link}) tai soittamalla *97.</p>',
    'mailtpl.fax_received.subject' => 'Uusi faksi vastaanotettu - {department} ({did})',
    'mailtpl.fax_received.body' => '<p>Uusi faksi on vastaanotettu.</p><ul><li><strong>Yksikkö:</strong> {department}</li><li><strong>Faksinumero:</strong> {did}</li><li><strong>Lähettäjä:</strong> {caller}</li><li><strong>Sivuja:</strong> {pages}</li><li><strong>Vastaanotettu:</strong> {date}</li></ul><p>Faksi liitetään PDF-tiedostona, kun asetus on päällä. Kaikki faksit ovat faksien saapuneissa: {portal_link}</p>',
    'mailtpl.fax_sent.subject' => 'Faksi toimitettu: {destination} (#{fax_id})',
    'mailtpl.fax_sent.body' => '<p>Faksisi on toimitettu.</p><ul><li><strong>Vastaanottaja:</strong> {destination}</li><li><strong>Sivuja:</strong> {pages}</li><li><strong>Aika:</strong> {date}</li></ul><p>Lähetetyt faksit: {portal_link}</p>',
    'mailtpl.fax_failed.subject' => 'Faksia EI toimitettu: {destination} (#{fax_id})',
    'mailtpl.fax_failed.body' => '<p>Faksiasi ei voitu toimittaa.</p><ul><li><strong>Vastaanottaja:</strong> {destination}</li><li><strong>Sivuja:</strong> {pages}</li><li><strong>Aika:</strong> {date}</li><li><strong>Syy:</strong> {error}</li></ul><p>Voit lähettää sen uudelleen portaalista: {portal_link}</p>',
    'mailtpl.test.subject' => '{brand} testiviesti ({date})',
    'mailtpl.test.body' => '<p>Tämä on testiviesti palvelusta <strong>{brand}</strong>. Jos pystyt lukemaan sen, sähköpostin lähetys toimii.</p><ul><li><strong>Lähetetty:</strong> {date}</li><li><strong>Lähettäjä:</strong> {from_name} &lt;{from_address}&gt;</li><li><strong>Vastaanottaja:</strong> {to}</li><li><strong>Palvelin:</strong> {host}</li></ul>',
