    'phones.allowed_networks_help' => 'Yksi verkko riviä kohden (esim. 192.168.1.0/24). Kun verkot on asetettu, niiden ulkopuoliset puhelimet eivät saa mitään, ja MAC-osoitteeseen perustuvat tiedostonimet (/provision/<mac file>) toimivat niiden sisällä. Tyhjä: vain puhelinkohtaiset URL-osoitteet toimivat, mistä tahansa.',
    'phones.addresses_help' => 'Kirjoitetaan puhelinten tiedostoihin. Tyhjä: vaihteen verkkotunnus. Puhelinverkossa ilman DNS:ää tai internetiä anna IP-osoitteet ja määritä puhelimet sitten uudelleen.',
    'phones.sip_server' => 'SIP-palvelin (rekisteröinti)',
