    'phones.base_url' => 'Määritysosoite',
    'phones.base_url_help' => 'Mistä puhelimet hakevat tiedostonsa: IP tai nimi, esim. 192.168.1.70 (käytetään http:tä), tai skeeman ja portin kanssa, esim. https://pbx.example.com:8443 (ilman polkua). Näytetään jokaisen puhelimen kohdalla ja lähetetään DHCP-valintana 66/160. IP-osoitteella https:n kautta varmenne ei vastaa osoitetta: useimmat puhelimet hyväksyvät sen, jotkin vaativat http:n.',
    'phones.tftp_export' => 'Kirjoita puhelinten tiedostot myös TFTP/FTP-kansioon',
    'phones.tftp_export_help' => 'Puhelimille, jotka hakevat määrityksensä TFTP:llä tai FTP:llä (NEC). Jokaisen määritetyn puhelimen tiedosto (esim. dt-<MAC>.cfg) pidetään siellä ajan tasalla viimeistään 5 minuutin kuluttua muutoksesta. Tiedostoissa on SIP-salasana; TFTP ja FTP vastaavat vain yllä sallituille verkoille.',
    'phones.ntp_help' => 'Nimi tai IP-osoite. NEC-puhelimet hyväksyvät vain IP-osoitteen. Kun Verkkopalvelut → NTP-palvelin on päällä, anna tämän palvelimen IP.',
