    'phones.help_title' => 'Miten provisiointi toimii?',
    'phones.help_body' => 'Puhelin hakee asetuksensa HTTPS:llä AiPBX:stä ja rekisteröityy alanumerollaan, näppäimillään ja asetuksillaan. Jokainen lataus kirjataan alle.',
    'phones.help_url' => 'Puhelinkohtainen URL:',
