    'phones.import_btn' => 'Tuo',
    'phones.import_desc' => 'Yksi puhelin riviä kohden: MAC, malli, alanumero. Malli on tällä sivulla näkyvä nimi tai sen avain (yealink-t46u). Tunnettu MAC päivitetään.',
