    'phones.col_region' => 'Alue',
    'phones.region_title' => 'Alueet',
    'phones.region_help' => 'Puhelin saa alueensa osoitteet ja asetukset, esimerkiksi yhdet verkkosi sisällä ja toiset sen ulkopuolella oleville puhelimille. Valitset alueen kussakin puhelimessa; uudet puhelimet aloittavat oletusalueella. Tyhjä kenttä ottaa arvon yleisistä asetuksista. Sallitut verkot pysyvät yleisinä, ja ulkopuolella olevat puhelimet tarvitsevat myös palvelimen NAT-asetusten, palomuurin ja varmenteen olevan kunnossa. Puhelimen on silti otettava yhteys palvelimeen kerran lukeakseen alueensa asetukset.',
    'phones.region_default' => 'Oletus',
    'phones.region_defaults_title' => 'Yleiset asetukset kaikille alueille',
    'phones.region_defaults_help' => 'Jokainen alue käyttää näitä, ellei alueella ole omaa arvoa kentälle: silloin käytetään alueen arvoa.',
