    'phones.region_transport' => 'Siirtoyhteys',
    'phones.region_sip_port' => 'SIP-portti',
    'phones.region_sip_port_help' => 'Näille puhelimille lisättyä siirtoyhteyttä varten. Tyhjä: valitun siirtoyhteyden portti.',
    'phones.region_sip443' => 'SIP TLS-yhteydellä portissa 443',
    'phones.region_sip443_help' => 'Verkoille, jotka sallivat lähtevän TLS-liikenteen vain portissa 443. Nämä puhelimet saavat TLS-yhteyden ja portin 443. Anna alueelle oma SIP-palvelinnimi (esimerkiksi sip1.example.com, joka osoittaa tähän palvelimeen DNS:ssä): kyseisellä nimellä tulevat yhteydet menevät PBX:ään, kaikki muu portissa 443 säilyy ennallaan. Let\'s Encrypt lisää nimen varmenteeseen, kun se pyydetään uudelleen. Puhelut tarvitsevat silti ääniliikenteen (UDP) läpimenon. PBX näkee nämä puhelimet osoitteena 127.0.0.1, joten fail2ban ei estä niitä.',
    'phones.region_sip443_sources' => 'Osoitteet SIP-yhteydelle portissa 443 ilman omaa nimeä',
    'phones.region_sip443_sources_help' => 'Vain silloin, kun alueella ei ole omaa SIP-palvelinnimeä (tyhjä, IP-osoite tai portaalin nimi): näiden puhelimien osoitteet tai verkot pilkuilla eroteltuina. Niistä selaimet ja sovellukset eivät voi käyttää TURN-protokollaa portissa 443.',
    'phones.region_sip443_cert' => 'Pyydä Let\'s Encrypt -varmenne uudelleen Varmenteet-sivulla, jotta se sisältää myös kohteen %s.',
