    'phones.copy_https' => 'Kopioi HTTPS-osoite portaalin nimen alla. Puhelimen on pystyttävä saavuttamaan kyseinen nimi ja luotettava sen varmenteeseen.',
    'phones.extra_help_snom' => 'Snom: voit myös liittää Snom XML:ää, yksittäisiä rivejä tai koko tiedoston, kuten <code>&lt;language perm="RW"&gt;Deutsch&lt;/language&gt;</code>.',
