    'phones.extra_title' => 'Mallin asetukset',
    'phones.extra_model' => 'Puhelinmalli',
    'phones.extra_help' => 'Asetukset, jotka lisätään siihen, mitä AiPBX kirjoittaa jokaiselle tämän mallin puhelimelle, yksi <code>name = value</code> riviä kohden; # aloittaa kommentin. Asetus, jonka myös AiPBX kirjoittaa, saa tässä annetun arvon, ja päivitys säilyttää nämä. Nimet ja arvot siirtyvät puhelimeen sellaisinaan, joten virheellinen arvo voi estää puhelinta toimimasta. Puhelimet lukevat ne, kun ne seuraavan kerran hakevat asetuksensa, yleensä uudelleenkäynnistyksen yhteydessä. Saatavilla laitteille NEC, Yealink, Grandstream ja Poly.',
