    'storage.help_title' => 'Missä chat-tiedostot säilytetään',
    'storage.help_body' => '<p>Chat-liitteet, niiden pikkukuvat ja ryhmäkuvat tallennetaan oletuksena palvelimen levylle (<code>/var/lib/aipbx/chat_files</code>). S3-yhteensopivalla tallennustilalla (AWS S3, MinIO, Wasabi, Backblaze B2, Cloudflare R2 …) ne menevät sen sijaan säilöön, eivätkä suuret tiedostot kuormita PBX:ää.</p><p>Lataukset kulkevat edelleen chat-palvelun kautta, joten vain chatin osallistujat voivat avata sen tiedostot; säilö voi pysyä yksityisenä. Ennen vaihtoa tallennetut tiedostot tarjoillaan levyltä, kunnes siirrät ne. Säilön asetukset tarkistetaan ennen tallennusta.</p><p>Puhelutallenteet, puhelinvastaaja ja faksit pysyvät paikallisella levyllä.</p>',
