    'storage.path_style' => 'Polkumuotoiset osoitteet (https://host/bucket/…). Tarvitaan MinIO:lle ja useimmille omille palvelimille; poista käytöstä AWS S3:lle.',
    'storage.recordings' => 'Puhelutallenteet myös bucketiin',
    'storage.recordings_help' => 'Valmiit tallenteet (MP3) siirtyvät bucketiin minuuteissa ja poistuvat palvelimen levyltä; vanhemmat seuraavat erissä. Kuuntelu ja lataus pysyvät ennallaan.',
    'storage.faxes' => 'Faksit myös bucketiin',
    'storage.faxes_help' => 'Vastaanotettujen ja lähetettyjen faksien PDF ja TIFF siirtyvät bucketiin tunti valmistumisen jälkeen ja poistuvat palvelimen levyltä. Katselu, lataus, uudelleenlähetys ja poisto pysyvät ennallaan.',
    'storage.voicemail_days' => 'Arkistoi kuunnellut vastaajaviestit, jotka ovat vanhempia kuin (päivää)',
    'storage.voicemail_days_help' => '0 = ei koskaan. Tätä vanhemmat kuunnellut viestit siirtyvät bucketiin ja poistuvat palvelimelta; ne näkyvät, soivat ja poistetaan edelleen portaalissa ja sovelluksissa, mutta eivät enää pöytäpuhelimesta. Uusia viestejä ei koskaan siirretä.',
