    'health.msg_vpn_unavailable' => 'VPN-apuohjelma ei vastannut, joten VPN:n tila ei ole tiedossa',
    'vpn.err_unavailable' => 'VPN-apuohjelma ei vastannut. Se, mitä tämä sivu näyttää, ei välttämättä ole todellinen tila, joten älä muuta mitään, ennen kuin se vastaa.',
    'fax.err_did_digits' => 'Numero voi sisältää vain numeroita sekä valinnaisen +-merkin alussa.',
    'health.desc_vpn' => 'Päällä ollessaan: VPN-palvelin on käynnissä ja VPN-yhteydet ovat aktiivisia',
    'vpn.server_title' => 'VPN-palvelin',
    'vpn.client_title' => 'VPN-asiakas',
    'vpn.server_help' => 'Mahdollistaa verkon ulkopuolella olevien puhelimien, ohjelmistopuhelinten ja kannettavien tietokoneiden yhteyden tähän PBX:ään suojatun tunnelin kautta. Valitse <strong>WireGuard</strong> (nopea ja yksinkertainen, suositeltu) tai <strong>OpenVPN</strong> (kun laite vaatii sitä tai kun vain TCP pääsee palomuurin läpi). Lisää laite ja lataa sen profiili kyseiseen laitteeseen; jokaisella laitteella on omat avaimensa, ja sen poistaminen sulkee sen välittömästi ulos. Rekisteröi puhelimet Laitteet-kohdassa näkyvään palvelimen VPN-osoitteeseen.<br><br><strong>Mitä VPN-laite voi tavoittaa:</strong> vain tämän PBX:n: portaalin, SIP:n, puheluäänen ja faksin. Se ei voi tavoittaa muita laitteita tai tämän palvelimen takana olevia verkkoja, koska palvelin ei reititä verkkojen välillä. SSH sekä FTP- ja TFTP-palvelut eivät ole avoinna sille. Toiseen VPN-tyyppiin siirtyminen antaa laitteille uudet profiilit; vanhan tyypin laitteet säilytetään ja ne toimivat jälleen, kun palaat takaisin. Myös portin tai julkisen osoitteen muuttaminen vaatii profiilien lataamisen uudelleen.',
    'vpn.client_help' => 'Yhdistää tämän PBX:n toiseen verkkoon, esimerkiksi SIP-runkolinjaan tai toiseen PBX:ään, joka on tavoitettavissa vain VPN-yhteyden kautta. Lataa palveluntarjoajasi antama profiili (WireGuard <code>.conf</code> tai OpenVPN <code>.ovpn</code>) ja luettele tunnelin takana olevat verkot.<br><br><strong>Vain luettelemasi verkot käyttävät tunnelia.</strong> Profiili, joka lähettää kaiken liikenteen VPN:ään, hyväksytään, mutta PBX ei koskaan reititä kaikkea sen kautta: puhelut, runkolinjat ja pääsy tälle palvelimelle siirtyisivät myös ja yhteys voisi katketa. Tämän palvelimen jo käyttämää verkkoa ei voi luetella. Profiilin DNS-asetukset ohitetaan.<br><br><strong>Vain turvalliset asetukset hyväksytään.</strong> Nämä tiedostot voivat suorittaa komentoja palvelimella (<code>PostUp</code>, <code>up</code>, <code>plugin</code> ja muut), joten profiili, jossa on tällainen rivi, hylätään, ja varmenteiden on oltava OpenVPN-tiedoston sisällä polun nimeämisen sijaan. Profiilissa olevia IPv6-osoitteita ei käytetä.',
