    'netsvc.help_title' => 'Verkkopalvelut',
    'netsvc.help_body' => 'Pöytäpuhelimet löytävät provisiointipalvelimen itse, kun DHCP-palvelin jakaa sen osoitteen (optio 66). DHCP ja TFTP kytketään päälle erikseen. Kun <strong>DHCP-palvelin</strong> on pois päältä, oma DHCP-palvelimesi pysyy käytössä: aseta siihen alla luetellut optiot. Kun se on päällä, AiPBX jakaa osoitteita yhdessä liitännässä tai VLANissa. <strong>TFTP-palvelin</strong> tarjoaa lataamasi käynnistystiedostot ja laiteohjelmiston. Puhelinkohtainen asetustiedosto (SIP-salasanoineen) tarjoillaan aina HTTPS:n kautta, ei koskaan TFTP:llä.',
