    'web_widgets.help_body' => 'Widget lisää "Soita meille" -painikkeen mille tahansa verkkosivustolle. Kävijät puhuvat kanssasi selaimesta WebRTC:n kautta tai jättävät numeronsa, ja PBX soittaa heille. Liitä yksirivinen koodi verkkosivustolle (tai WordPress-lisäosaan) ja paina tallennuksen jälkeen <strong>Ota käyttöön</strong>.',
    'web_widgets.help_number' => 'Numero:',
    'web_widgets.help_number_desc' => 'Widget tulee PBX:ään kuten runkolinja. Sen numero on näiden puheluiden DID raporteissa ja CDR:ssä; kävijä ei koskaan valitse, minne puhelu menee.',
    'web_widgets.help_security' => 'Tietoturva:',
    'web_widgets.help_security_desc' => 'Vain sallitut verkkosivustot voivat käyttää widgetiä. Jokainen puhelu tarvitsee kertakäyttöisen tunnisteen, ja rajat (IP:tä kohden, päivässä, samanaikaiset puhelut, puhelun pituus) koskevat jokaista pyyntöä. Jokainen pyyntö kirjataan alle.',
    'web_widgets.help_callback' => 'Takaisinsoitto:',
    'web_widgets.help_callback_desc' => 'PBX soittaa kävijälle valitun lähtevän reitin kautta ja ohjaa hänet vastattaessa kohteeseen. Vain sallituilla etuliitteillä alkaviin numeroihin soitetaan, ja päiväraja on pakollinen.',
