    'health.title' => 'Kuntotarkistukset',
    'health.header_title' => 'Kuntotarkistukset',
    'health.help_title' => 'Miten kuntotarkistukset toimivat',
    'health.help_body' => '<p>Palvelin tarkistaa itsensä taustalla (suorittaa joka minuutti erääntyvät tarkistukset) ja lähettää sähköpostia valituille henkilöille, kun jokin lakkaa toimimasta, ja uudelleen, kun se toimii taas. Jokaisella tarkistuksella on oma aikavälinsä; <strong>Pois päältä</strong> kytkee sen pois.</p><p>Lyhyistä häiriöistä johtuvien hälytysten välttämiseksi tarkistukset, jotka suoritetaan 15 minuutin välein tai useammin, ilmoittavat ongelmasta vasta kahden peräkkäisen huonon tuloksen jälkeen. Ongelman jatkuessa hälytys toistetaan valitun tuntimäärän jälkeen. <strong>Tarkista nyt</strong> suorittaa jokaisen tarkistuksen minuutin kuluessa.</p><p><strong>Päivittäinen yhteenveto</strong> lähetetään samoille henkilöille: eilisen puhelut ja faksit sekä jokaisen tarkistuksen tila. Komentorivi: <code>sudo aipbx-selftest</code>. Katso docs/health.md.</p><p>Kun koko palvelin on alhaalla, se ei voi itse lähettää sähköpostia; valvo sitä sitä varten ulkopuolelta.</p>',
    'health.col_check' => 'Tarkistus',
    'health.col_status' => 'Tila',
