    'health.alarms_title' => 'Hälytyssähköpostit',
    'health.alarms_help' => 'Kuka saa sähköpostin, kun tarkistus epäonnistuu tai varoittaa, ja kun se toimii taas. Samat henkilöt saavat päivittäisen yhteenvedon.',
