    'health.quiet' => 'Hiljaiset tunnit varoituksille',
    'health.quiet_help' => 'Ei varoitussähköposteja tässä aikaikkunassa (TT:MM-TT:MM, voi ylittää keskiyön). Kriittinen virhe lähetetään silti heti, ja jatkuva ongelma lähetetään aikaikkunan päätyttyä. Tyhjä tarkoittaa ei hiljaisia tunteja.',
    'health.err_quiet' => 'Syötä hiljaiset tunnit muodossa TT:MM-TT:MM tai jätä kenttä tyhjäksi.',
    'health.summary_title' => 'Päivittäinen yhteenveto',
    'health.summary_help' => 'Joka aamu: eilisen puhelut (saapuvat, lähtevät, sisäiset, vastatut, vastaamatta jääneet, puheaika), faksit, eilisen hälytykset ja jokaisen tarkistuksen tila.',
    'health.summary_enabled' => 'Lähetä päivittäinen yhteenveto',
