    'health.templates_hint' => 'Näiden sähköpostien tekstejä voidaan muuttaa kohdassa Sähköposti → Mallit (Kuntohälytys, Kunto palautunut normaaliksi, Päivittäinen yhteenveto).',
    'health.err_email' => 'Ei ole sähköpostiosoite: %s',
