    'call_quality.title' => 'Puhelunlaatu',
    'call_quality.header_title' => 'Puhelunlaatu (RTCP)',
    'call_quality.help_title' => 'Miten se mitataan',
    'call_quality.help_body' => '<p>Jokainen puheluhaara raportoi oman äänenlaatunsa RTCP:ssä. Kun signaloinnin sieppaus on päällä (PBX-asetukset → Signalointi), AiPBX lukee nämä raportit minuutin välein: pakettihäviö ja jitter puheluhaaraa, runkolinjaa ja alanumeroa kohti. PBX:ssä ei muuteta mitään.</p><p><strong>Sisään</strong> on se, mitä tämä PBX vastaanotti, <strong>ulos</strong> se, mitä toinen osapuoli vastaanotti. Runkolinja, joka menettää ääntä <em>sisään</em>-suunnassa, viittaa operaattorin päähän, <em>ulos</em>-suunnassa meidän päähämme (lähetyskaista, palomuuri, kaistanleveys); alanumero, joka menettää ääntä <em>ulos</em>-suunnassa, on usein puhelin huonossa Wi-Fi-verkossa.</p><p>Haara on <strong>heikko</strong>, kun kaksi sen raporttia samaan suuntaan saavuttaa alla asetetun häviön, <strong>kohtalainen</strong> %s %%:sta alkaen. Jitter on RTP-aikaleimayksikköinä (8 = 1 ms G.711:lle). Runkolinja tai alanumero, joka menettää ääntä, on kuntotarkistuksen "Puhelunlaatu" ongelma: se näkyy hälytyskellossa ja lähetetään sähköpostitse muiden hälytysten tapaan.</p>',
    'call_quality.capture_off' => 'Signaloinnin sieppaus on pois päältä, joten mitään ei mitata.',
    'call_quality.capture_off_link' => 'Ota se käyttöön kohdassa PBX-asetukset → Signalointi',
    'call_quality.no_reports' => 'Ei RTCP-raportteja viimeisen 24 tunnin aikana. Soita puhelu; ensimmäiset mittaukset näkyvät minuutti sen jälkeen.',
    'call_quality.last_report' => 'Viimeisin RTCP-raportti: %s.',
    'call_quality.last_pass' => 'Viimeisin ajo %d s sitten.',
