    'phonelogs.help_body' => '<p>Pöytäpuhelimet lähettävät lokinsa (syslog, UDP 514) tälle palvelimelle, kun <strong>Syslog</strong> on päällä kohdassa <em>Verkkopalvelut</em> ja puhelimilla on tämä palvelin syslog-palvelimenaan (<em>Provisiointi → Alueet → Syslog-palvelin</em>; NEC-puhelimet saavat sen tiedostonsa mukana). Vain sallitut verkot kohdassa Provisiointi → Alueet hyväksytään.</p><p>Kirjoita <strong>IP-</strong> tai <strong>MAC-osoite</strong> nähdäksesi yhden puhelimen ja tekstiä rajataksesi rivejä. Kun <em>Live</em> on päällä, uudet rivit tulevat muutaman sekunnin välein. Lokia säilytetään noin 100 Mt; vanhemmat rivit poistetaan.</p>',
