    'license.modal_title' => 'Avoimen lähdekoodin lisenssi ja televiestinnän vastuuvapauslauseke',
    'license.intro' => 'AiPBX on ilmainen ja avoimen lähdekoodin ohjelmisto, joka on julkaistu MIT-lisenssillä ja toimitetaan "SELLAISENA KUIN SE ON" (AS IS) ilman minkäänlaista takuuta. Käyttämällä tätä PBX-järjestelmää hyväksyt seuraavat ehdot:',
    'license.item_oss' => 'Ei takuuta (MIT-lisenssi): Tekijät ja avustajat eivät ole vastuussa mistään suorista, epäsuorista tai välillisistä vahingoista, jotka aiheutuvat tämän ohjelmiston käytöstä.',
    'license.item_emergency' => 'Hätäpuhelut (112 / 911 / 999): AiPBX ei ole sertifioitu hätäpuhelupalvelu. Sähkökatkot, internet-häiriöt tai SIP-runkolinjan katkokset voivat estää hätäpuhelut. Varmista aina erillinen ja riippumaton varayhteys hätäpuheluille.',
    'license.item_fraud' => 'Teleoperaattorilaskutus ja puhelinpetokset (Toll Fraud): Palvelinpääsyn suojaaminen, vahvojen SIP-/ylläpitotunnusten käyttäminen ja lähtevien reittien rajoittaminen ovat täysin omalla vastuullasi. Tekijät eivät ole vastuussa operaattorimaksuista tai luvattomasta käytöstä.',
    'license.item_privacy' => 'Tietosuoja ja puhelun tallennus (GDPR / KVKK): Puhelujen tallennuksen, faksien arkistoinnin tai tekoälypuheentunnistuksen käyttöönotto edellyttää sovellettavien soittajan suostumusta ja tietosuojaa koskevien lakien noudattamista omalla lainkäyttöalueellasi.',
    'license.checkbox_label' => 'Olen lukenut, ymmärtänyt ja hyväksyn MIT-lisenssin sekä televiestinnän vastuuvapauslausekkeen.',
