    'firewall.help_common' => 'Yleiset-välilehti sisältää säännöt, joita jokainen verkkokortti käyttää: se mitä lisäät, poistat tai otat siellä pois päältä, koskee kaikkia kortteja. Virtuaaliset liitännät, joilla on omat sääntönsä (kuten VPN), eivät käytä yleisiä sääntöjä; niiden välilehti luettelee kaiken mitä ne avaavat, ja niiden säännöt määritetään siellä. Kortin oma välilehti näyttää vain siitä poikkeavat asiat: vain kyseistä korttia koskevat säännöt sekä siitä suljetut yleiset säännöt. Yleiset-välilehdellä korttipainikkeet sulkevat tai avaavat säännön yhdellä kortilla. Poista sääntö tilapäisesti käytöstä kokeilua varten poistamatta sitä kokonaan; se palaa entiselleen, kun kytket sen takaisin päälle. Lähdemäärityksellä vain kyseinen osoite tai verkko saa käyttää porttia. Ennen muutosta, joka voi katkaista yhteytesi, puhelut tai puhelimet, sivu ilmoittaa mitä se tekee.',
    'firewall.virtual_own' => 'Virtuaalinen liitäntä (esimerkiksi VPN): yleiset säännöt eivät päde tässä. Se avaa vain alla olevat säännöt; lisää tähän, mitä sen tulee avata.',
